// migrateArc lifts a v1 arc into the v2 shape.
func migrateArc(ctx context.Context, old v1.Arc) (Arc, error) {
	migrated, err := autoMigrateArc(ctx, old)
	if err != nil {
		return Arc{}, err
	}
	// Text is now stored as a replicated document; seed it from the previously
	// persisted raw source. Raw itself is derived and no longer persisted.
	migrated.Text.Doc = text.Create(old.Text.Raw)
	migrated.Text.Raw = ""
	return migrated, nil
}

